gMa(){return"\u05d0\u05ea \u05d4\u05de\u05d7\u05d9\u05e7\u05d4 \u05e6\u05e8\u05d9\u05da \u05dc\u05d0\u05e9\u05e8 \u05d0\u05d3\u05dd \u05d0\u05d7\u05e8 \u05de\u05d6\u05d4 \u05e9\u05d4\u05e6\u05d9\u05e2 \u05d0\u05d5\u05ea\u05d4"},
gM5(){return"\u05d0\u05d9 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d1\u05e6\u05e2 \u05d0\u05ea \u05d4\u05e9\u05d9\u05e0\u05d5\u05d9 \u05d4\u05d6\u05d4"},
gM8(){return"\u05d4\u05e4\u05e2\u05d5\u05dc\u05d4 \u05d4\u05d6\u05d5 \u05e2\u05d3\u05d9\u05d9\u05df \u05dc\u05d0 \u05d6\u05de\u05d9\u05e0\u05d4 \u05d1\u05e9\u05e8\u05ea \u05d4\u05de\u05d7\u05d5\u05d1\u05e8"},
gOk(){return"\u05e1\u05d9\u05d1\u05d4 (\u05e0\u05e8\u05e9\u05de\u05ea \u05d1\u05d9\u05d5\u05de\u05df)"},
Oj(a){return"\u05dc\u05e4\u05d7\u05d5\u05ea "+a+" \u05ea\u05d5\u05d5\u05d9\u05dd. \u05d1\u05dc\u05d9 \u05dc\u05d4\u05e2\u05ea\u05d9\u05e7 \u05ea\u05d5\u05db\u05df \u05e9\u05dc \u05de\u05e1\u05de\u05da \u05d0\u05d5 \u05e9\u05dc \u05e6\u05f3\u05d0\u05d8"},
BJ(a){return"\u05d9\u05e9 \u05dc\u05db\u05ea\u05d5\u05d1 \u05dc\u05e4\u05d7\u05d5\u05ea "+a+" \u05ea\u05d5\u05d5\u05d9\u05dd"},
gAJ(){return"\u05d9\u05e9 \u05dc\u05e1\u05de\u05df \u05db\u05d3\u05d9 \u05dc\u05d4\u05de\u05e9\u05d9\u05da"},
gRn(){return"\u05de\u05e1\u05de\u05db\u05d9 \u05d0\u05e9\u05e8\u05d4"},
gRm(){return"\u05d4\u05e7\u05d1\u05e6\u05d9\u05dd \u05de\u05e1\u05d5\u05d3\u05e8\u05d9\u05dd \u05dc\u05e4\u05d9 \u05d4\u05d6\u05de\u05df \u05e9\u05e0\u05e9\u05d0\u05e8 \u05e2\u05d3 \u05d4\u05de\u05d7\u05d9\u05e7\u05d4. \u05db\u05dc \u05e7\u05d5\u05d1\u05e5 \u05e0\u05de\u05d7\u05e7 \u05de\u05d9\u05d3 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05d4\u05d7\u05dc\u05d8\u05d4, \u05d5\u05dc\u05db\u05dc \u05d4\u05de\u05d0\u05d5\u05d7\u05e8 24 \u05e9\u05e2\u05d5\u05ea \u05d0\u05d7\u05e8\u05d9 \u05d4\u05d4\u05e2\u05dc\u05d0\u05d4, \u05d2\u05dd \u05d1\u05e9\u05d9\u05e9\u05d9 \u05d5\u05d1\u05e9\u05d1\u05ea"},
Rt(a){return"\u05de\u05de\u05ea\u05d9\u05e0\u05d9\u05dd \u05dc\u05d4\u05d7\u05dc\u05d8\u05d4 ("+a+")"},
