R2(a){return"\u05d4\u05d5\u05e2\u05dc\u05d4 "+a},
Pe(a){return"\u05d4\u05d2\u05e9\u05d4 \u05d7\u05d5\u05d6\u05e8\u05ea \xb7 \u05d4\u05d0\u05d9\u05e9\u05d5\u05e8 \u05d4\u05e7\u05d5\u05d3\u05dd \u05d1\u05ea\u05d5\u05e7\u05e3 \u05e2\u05d3 "+a},
BU(a){return"\u05e0\u05e9\u05dc\u05d7\u05d4 \u05d1\u05e7\u05e9\u05d4 \u05dc\u05d4\u05e2\u05dc\u05d0\u05d4 \u05d7\u05d5\u05d6\u05e8\u05ea "+a},
LN(a){return"\u05d9\u05d9\u05de\u05d7\u05e7 \u05d1\u05e2\u05d5\u05d3 "+a},
Mz(a,b){return""+a+" \u05e9\u05f3 "+b+" \u05d3\u05f3"},
