gP5(){return"\u05d6\u05d4 \u05dc\u05d0 \u05de\u05e1\u05de\u05da \u05d0\u05e9\u05e8\u05d4"},
gP0(){return"\u05ea\u05d5\u05e7\u05e3 \u05d4\u05d0\u05e9\u05e8\u05d4 \u05e4\u05d2"},
