Fk(a){return A.aS(a,null,this.a,null,"\u05d4\u05d9\u05d5\u05dd \u05e9\u05e0\u05e9\u05d0\u05e8 \u05d1\u05ea\u05e7\u05d5\u05e4\u05d4 \u05d4\u05e0\u05d5\u05db\u05d7\u05d9\u05ea \u05dc\u05d0 \u05e2\u05d5\u05d1\u05e8 \u05dc\u05ea\u05e7\u05d5\u05e4\u05d4 \u05d4\u05d7\u05d3\u05e9\u05d4",""+a+" \u05d4\u05d9\u05de\u05d9\u05dd \u05e9\u05e0\u05e9\u05d0\u05e8\u05d5 \u05d1\u05ea\u05e7\u05d5\u05e4\u05d4 \u05d4\u05e0\u05d5\u05db\u05d7\u05d9\u05ea \u05dc\u05d0 \u05e2\u05d5\u05d1\u05e8\u05d9\u05dd \u05dc\u05ea\u05e7\u05d5\u05e4\u05d4 \u05d4\u05d7\u05d3\u05e9\u05d4",null,"\u05d4\u05d6\u05de\u05df \u05e9\u05e0\u05e9\u05d0\u05e8 \u05d1\u05ea\u05e7\u05d5\u05e4\u05d4 \u05d4\u05e0\u05d5\u05db\u05d7\u05d9\u05ea \u05dc\u05d0 \u05e2\u05d5\u05d1\u05e8 \u05dc\u05ea\u05e7\u05d5\u05e4\u05d4 \u05d4\u05d7\u05d3\u05e9\u05d4")},
Fl(a){return"\u05d4\u05e9\u05d9\u05d7\u05d5\u05ea \u05e9\u05dc \u05d4\u05de\u05e1\u05dc\u05d5\u05dc \u05d4\u05e0\u05d5\u05db\u05d7\u05d9 \u05d9\u05d9\u05e9\u05d0\u05e8\u05d5 \u05dc\u05e7\u05e8\u05d9\u05d0\u05d4 \u05d1\u05dc\u05d1\u05d3 \u05e2\u05d3 "+a+". \u05dc\u05d0 \u05ea\u05d5\u05db\u05dc\u05d5 \u05dc\u05e9\u05dc\u05d5\u05d7 \u05d1\u05d4\u05df \u05d4\u05d5\u05d3\u05e2\u05d5\u05ea \u05d0\u05d5 \u05dc\u05e7\u05d1\u05dc \u05de\u05d4\u05df \u05de\u05e1\u05e4\u05e8 \u05d8\u05dc\u05e4\u05d5\u05df"},
