gKn(){return"\u0417\u0430\u043f\u0438\u0441\u0430\u043d \u0440\u0435\u0433\u0438\u043e\u043d \u043b\u0438\u0446\u0435\u043d\u0437\u0438\u0438"},
gKL(){return"\u0421\u0431\u043e\u0439 \u0430\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u0447\u0442\u0435\u043d\u0438\u044f: \u0440\u0443\u0447\u043d\u0430\u044f \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430"},
gLg(){return"\u0420\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u043e\u0442\u043c\u0435\u043d\u0451\u043d"},
gAR(){return"\u041e\u0442\u043c\u0435\u043d\u0435\u043d\u043e"},
gLh(){return"\u0420\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u043f\u0435\u0440\u0435\u0441\u0442\u0430\u0451\u0442 \u0434\u0435\u0439\u0441\u0442\u0432\u043e\u0432\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u043c\u0435\u043d\u044f\u0435\u0442\u0441\u044f \u043c\u0430\u0440\u0448\u0440\u0443\u0442 \u0441\u0435\u043c\u044c\u0438 \u0438\u043b\u0438 \u043c\u0435\u0441\u0442\u043e \u0443\u0445\u043e\u0434\u0430."},
gLi(){return"\u0417\u0430\u043f\u0438\u0441\u0430\u043d\u043d\u044b\u0435 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u044b"},
gLS(){return"\u0411\u0435\u0437 \u0442\u0438\u043f\u0430 \u0438 \u043e\u0442\u0440\u0430\u0441\u043b\u0438 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0435\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u0434\u0430\u0442\u0430, \u0438 \u043a\u043e\u043d\u0442\u0430\u043a\u0442 \u043e\u0441\u0442\u0430\u0451\u0442\u0441\u044f \u0437\u0430\u043a\u0440\u044b\u0442\u044b\u043c (\xab\u043d\u0443\u0436\u043d\u0430 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430\xbb)."},
gLU(){return"\u0414\u0430\u043d\u043d\u044b\u0435 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0430"},
gMf(){return"\u0418\u0434\u0435\u043d\u0442\u0438\u0444\u0438\u043a\u0430\u0442\u043e\u0440 \u0438\u0437 \u043a\u0430\u0440\u0442\u043e\u0447\u043a\u0438 \u0441\u0435\u043c\u044c\u0438"},
gMg(){return"\u0418\u0434\u0435\u043d\u0442\u0438\u0444\u0438\u043a\u0430\u0442\u043e\u0440 \u0441\u0435\u043c\u044c\u0438"},
gMh(){return"\u041d\u0443\u0436\u0435\u043d \u0438\u0434\u0435\u043d\u0442\u0438\u0444\u0438\u043a\u0430\u0442\u043e\u0440 \u0441\u0435\u043c\u044c\u0438"},
gBf(){return"\u041c\u0430\u0440\u0448\u0440\u0443\u0442 \u0442\u0440\u0443\u0434\u043e\u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0430"},
gBg(){return"\u0420\u0430\u0431\u043e\u0447\u0438\u0439 \u0440\u0435\u0433\u0438\u043e\u043d"},
gBj(){return"\u0421\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u044c \u0440\u0435\u0433\u0438\u043e\u043d"},
gBk(){return"\u0417\u0430\u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u0440\u0435\u0433\u0438\u043e\u043d \u0441\u0438\u0434\u0435\u043b\u043a\u0438"},
MP(a){return"\u0416\u0438\u0432\u0451\u0442 \u0432: "+a},
gNp(){return"\u041f\u0440\u0438\u043c\u0435\u0447\u0430\u043d\u0438\u0435"},
gNq(){return"\u041f\u0440\u0438\u043c\u0435\u0447\u0430\u043d\u0438\u0435 (\u043d\u0435\u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u043e)"},
gNy(){return"\u041f\u0440\u043e\u0432\u0435\u0440\u0435\u043d\u043e \u0434\u043b\u044f \u044d\u0442\u043e\u0439 \u0441\u0435\u043c\u044c\u0438: \u043f\u043e \u044d\u0442\u043e\u043c\u0443 \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u0443 \u043c\u043e\u0436\u043d\u043e \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0430\u0442\u044c. \u041e\u0441\u0442\u0430\u043b\u044c\u043d\u044b\u0435 \u0443\u0441\u043b\u043e\u0432\u0438\u044f \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u044e\u0442\u0441\u044f \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e."},
gOz(){return"\u041f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u0443\u043f\u043e\u043b\u043d\u043e\u043c\u043e\u0447\u0435\u043d\u043d\u044b\u043c \u043e\u0440\u0433\u0430\u043d\u043e\u043c"},
gOA(){return"\u0418\u0437 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0430"},
gOC(){return"\u0413\u043e\u0440\u043e\u0434 \u043f\u0440\u043e\u0436\u0438\u0432\u0430\u043d\u0438\u044f"},
gOD(){return"\u0417\u0430\u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u0440\u0435\u0433\u0438\u043e\u043d \u043d\u0435 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u044f\u0435\u0442\u0441\u044f \u0432\u044b\u0431\u0440\u0430\u043d\u043d\u044b\u043c\u0438 \u0441\u0438\u0434\u0435\u043b\u043a\u043e\u0439 \u0433\u043e\u0440\u043e\u0434\u0430\u043c\u0438."},
