gTd(){return"\u0417\u0430\u0432\u0435\u0440\u0448\u0435\u043d\u043e"},
gS6(){return"\u0421\u0435\u043c\u044c\u044f \u0437\u0430\u0431\u043b\u043e\u043a\u0438\u0440\u043e\u0432\u0430\u043b\u0430 \u044d\u0442\u043e\u0442 \u0447\u0430\u0442. \u041d\u043e\u0432\u044b\u0435 \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u044f \u043e\u0442\u043f\u0440\u0430\u0432\u0438\u0442\u044c \u043d\u0435\u043b\u044c\u0437\u044f."},
gV_(){return"\u041c\u043e\u0448\u0435\u043d\u043d\u0438\u0447\u0435\u0441\u0442\u0432\u043e \u0438\u043b\u0438 \u043f\u043e\u043f\u044b\u0442\u043a\u0430 \u043e\u0431\u043c\u0430\u043d\u0430"},
gW3(){return"\u0420\u0430\u0437\u0431\u043b\u043e\u043a\u0438\u0440\u043e\u0432\u0430\u0442\u044c"},
gW4(){return"\u0411\u043b\u043e\u043a\u0438\u0440\u043e\u0432\u043a\u0430 \u0441\u043d\u044f\u0442\u0430"},
gX_(){return"\u0427\u0442\u043e \u0443\u0432\u0438\u0434\u044f\u0442 \u0441\u0435\u043c\u044c\u0438"},
gWX(){return"\u041b\u044e\u0431\u0430\u044f \u0441\u0435\u043c\u044c\u044f, \u043a\u043e\u0442\u043e\u0440\u0430\u044f \u0438\u0449\u0435\u0442 \u0441\u0438\u0434\u0435\u043b\u043a\u0443, \u043c\u043e\u0436\u0435\u0442 \u0432\u0438\u0434\u0435\u0442\u044c \u0432\u0430\u0448\u0435 \u0438\u043c\u044f, \u0432\u0438\u0434 \u0440\u0430\u0431\u043e\u0442\u044b, \u0433\u043e\u0440\u043e\u0434\u0430 \u0440\u0430\u0431\u043e\u0442\u044b, \u044f\u0437\u044b\u043a\u0438, \u0433\u043e\u0442\u043e\u0432\u043d\u043e\u0441\u0442\u044c \u0438 \u043e\u043f\u044b\u0442, \u043a\u0443\u0440\u0438\u0442\u0435 \u043b\u0438 \u0432\u044b, \u0434\u0430\u0442\u044b \u0437\u0430\u043c\u0435\u043d\u044b, \u043a\u043e\u0433\u0434\u0430 \u0432\u044b \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0438\u0439 \u0440\u0430\u0437 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u043b\u0438, \u0447\u0442\u043e \u0438\u0449\u0435\u0442\u0435 \u0440\u0430\u0431\u043e\u0442\u0443, \u0438 \u0441\u0442\u0430\u0442\u0443\u0441 \u0432\u0438\u0437\u044b."},
gWY(){return"\u041f\u043e\u0441\u043b\u0435 \u0442\u043e\u0433\u043e \u043a\u0430\u043a \u0432\u0430\u0448\u0430 \u0432\u0438\u0437\u0430 \u043f\u0440\u043e\u0432\u0435\u0440\u0435\u043d\u0430 \u0438 \u043e\u0434\u043e\u0431\u0440\u0435\u043d\u0430, \u0441\u0435\u043c\u044c\u044f, \u043e\u043f\u043b\u0430\u0442\u0438\u0432\u0448\u0430\u044f \u0434\u043e\u0441\u0442\u0443\u043f, \u043c\u043e\u0436\u0435\u0442 \u043d\u0430\u0447\u0430\u0442\u044c \u0441 \u0432\u0430\u043c\u0438 \u0447\u0430\u0442 \u0438 \u043f\u043e\u043b\u0443\u0447\u0438\u0442\u044c \u0432\u0430\u0448 \u043d\u043e\u043c\u0435\u0440 \u0442\u0435\u043b\u0435\u0444\u043e\u043d\u0430."},
gWZ(){return"\u0424\u0430\u0439\u043b \u0432\u0438\u0437\u044b \u0441\u0435\u043c\u044c\u044f\u043c \u043d\u0435 \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442\u0441\u044f. \u0421\u043e\u0442\u0440\u0443\u0434\u043d\u0438\u043a\u0438 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438 \u0432\u0438\u0437 \u0438 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0438 \u0432\u0438\u0434\u044f\u0442 \u0432\u0435\u0441\u044c \u0432\u0430\u0448 \u043f\u0440\u043e\u0444\u0438\u043b\u044c, \u0447\u0442\u043e\u0431\u044b \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u0442\u044c \u0441\u0432\u043e\u044e \u0440\u0430\u0431\u043e\u0442\u0443."},
gWA(){return"\u0424\u0430\u0439\u043b \u043d\u0435 \u0443\u0434\u0430\u043b\u043e\u0441\u044c \u043f\u0440\u043e\u0447\u0438\u0442\u0430\u0442\u044c. \u041e\u0442\u0441\u043a\u0430\u043d\u0438\u0440\u0443\u0439\u0442\u0435 \u0438\u043b\u0438 \u0441\u0444\u043e\u0442\u043e\u0433\u0440\u0430\u0444\u0438\u0440\u0443\u0439\u0442\u0435 \u0432\u0438\u0437\u0443 \u0435\u0449\u0451 \u0440\u0430\u0437, \u0447\u0442\u043e\u0431\u044b \u0432\u0441\u0451 \u0431\u044b\u043b\u043e \u0447\u0451\u0442\u043a\u043e \u0432\u0438\u0434\u043d\u043e, \u0438 \u0437\u0430\u0433\u0440\u0443\u0437\u0438\u0442\u0435 \u0435\u0451 \u0441\u043d\u043e\u0432\u0430."},
gWB(){return"\u0417\u0430\u0433\u0440\u0443\u0436\u0435\u043d\u043d\u044b\u0439 \u0444\u0430\u0439\u043b \u2014 \u044d\u0442\u043e \u043d\u0435 \u0432\u0438\u0437\u0430. \u0417\u0430\u0433\u0440\u0443\u0437\u0438\u0442\u0435 \u0441\u0430\u043c \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442 \u0432\u0438\u0437\u044b."},
gWy(){return"\u0421\u0440\u043e\u043a \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f \u0432\u0438\u0437\u044b \u0432 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0435 \u0443\u0436\u0435 \u0438\u0441\u0442\u0451\u043a. \u0417\u0430\u0433\u0440\u0443\u0437\u0438\u0442\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044e\u0449\u0443\u044e \u0432\u0438\u0437\u0443."},
gWx(){return"\u0414\u0430\u0442\u0430 \u043e\u043a\u043e\u043d\u0447\u0430\u043d\u0438\u044f, \u043a\u043e\u0442\u043e\u0440\u0443\u044e \u0432\u044b \u0432\u0432\u0435\u043b\u0438, \u043d\u0435 \u0441\u043e\u0432\u043f\u0430\u043b\u0430 \u0441 \u0434\u0430\u0442\u043e\u0439 \u0432 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0435. \u0417\u0430\u0433\u0440\u0443\u0437\u0438\u0442\u0435 \u0432\u0438\u0437\u0443 \u0435\u0449\u0451 \u0440\u0430\u0437 \u0438 \u0432\u0432\u0435\u0434\u0438\u0442\u0435 \u0434\u0430\u0442\u0443 \u0442\u043e\u0447\u043d\u043e \u0442\u0430\u043a, \u043a\u0430\u043a \u043e\u043d\u0430 \u043d\u0430\u043f\u0438\u0441\u0430\u043d\u0430 \u0432 \u0432\u0438\u0437\u0435."},
gWz(){return"\u0412\u0438\u0437\u0430 \u043d\u0435 \u043e\u0434\u043e\u0431\u0440\u0435\u043d\u0430. \u0412\u044b \u043c\u043e\u0436\u0435\u0442\u0435 \u043e\u0431\u0440\u0430\u0442\u0438\u0442\u044c\u0441\u044f \u0432 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0443, \u0447\u0442\u043e\u0431\u044b \u0443\u0437\u043d\u0430\u0442\u044c \u043f\u043e\u0434\u0440\u043e\u0431\u043d\u0435\u0435, \u0438 \u0437\u0430\u0433\u0440\u0443\u0437\u0438\u0442\u044c \u0435\u0451 \u0441\u043d\u043e\u0432\u0430."},
gWE(){return"\u0421\u043e\u0442\u0440\u0443\u0434\u043d\u0438\u043a\u0438 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438 \u043f\u043e\u043f\u0440\u043e\u0441\u0438\u043b\u0438 \u0437\u0430\u0433\u0440\u0443\u0437\u0438\u0442\u044c \u0432\u0438\u0437\u0443 \u0435\u0449\u0451 \u0440\u0430\u0437. \u042d\u0442\u043e \u0435\u0449\u0451 \u043d\u0435 \u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u043f\u043e \u0432\u0430\u0448\u0435\u0439 \u0432\u0438\u0437\u0435."},
gRX(){return"\u0410\u043a\u043a\u0430\u0443\u043d\u0442"},
gCs(){return"\u0410\u0434\u043c\u0438\u043d\u0438\u0441\u0442\u0440\u0430\u0442\u043e\u0440 \u0441\u0438\u0441\u0442\u0435\u043c\u044b"},
gCt(){return"\u042f\u0437\u044b\u043a \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u044f \u0438 \u0447\u0430\u0442\u0430"},
gCv(){return"\u041a\u043e\u0433\u0434\u0430 \u0432\u044b \u0441\u0432\u043e\u0431\u043e\u0434\u043d\u044b"},
gRZ(){return"\u041d\u0430\u0437\u0430\u0434 \u0432 \u0447\u0430\u0442"},
gS8(){return"\u0421\u0435\u043c\u044c\u044f"},
gSb(){return"\u0421\u043a\u0440\u044b\u0442\u044c \u043e\u0440\u0438\u0433\u0438\u043d\u0430\u043b"},
gCD(){return"\u0421\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u044f \u0430\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u043f\u0435\u0440\u0435\u0432\u043e\u0434\u0438\u0442 \u0432\u043d\u0435\u0448\u043d\u0438\u0439 \u0441\u0435\u0440\u0432\u0438\u0441 \u043f\u0435\u0440\u0435\u0432\u043e\u0434\u0430. \u041f\u0435\u0440\u0435\u0432\u043e\u0434 \u043c\u043e\u0436\u0435\u0442 \u0431\u044b\u0442\u044c \u043d\u0435\u0442\u043e\u0447\u043d\u044b\u043c."},
gSv(){return"\u0412\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u0433\u043e\u0440\u043e\u0434\u0430"},
gSw(){return"\u0412\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u0433\u043e\u0440\u043e\u0434"},
