gSP(){return"\u041d\u0430\u043f\u0438\u0441\u0430\u0442\u044c \u0430\u0434\u043c\u0438\u043d\u0438\u0441\u0442\u0440\u0430\u0442\u043e\u0440\u0443 \u0441\u0438\u0441\u0442\u0435\u043c\u044b"},
gSY(){return"\u0423\u0434\u0430\u043b\u0438\u0442\u044c \u0430\u043a\u043a\u0430\u0443\u043d\u0442"},
gTj(){return"\u0414\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u044b"},
gCH(){return"\u0420\u0435\u0434\u0430\u043a\u0442\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u043f\u0440\u043e\u0444\u0438\u043b\u044c"},
gTo(){return"\u0417\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u044c \u043f\u043e\u0438\u0441\u043a"},
gTn(){return"\u0415\u0441\u043b\u0438 \u0432\u044b \u0443\u0436\u0435 \u043d\u0430\u0448\u043b\u0438 \u0440\u0430\u0431\u043e\u0442\u0443, \u0441\u043e\u043e\u0431\u0449\u0438\u0442\u0435 \u043d\u0430\u043c \u043e\u0431 \u044d\u0442\u043e\u043c \u043e\u0434\u043d\u0438\u043c \u043d\u0430\u0436\u0430\u0442\u0438\u0435\u043c."},
gTl(){return"\u0412\u0430\u0448\u0430 \u0430\u043d\u043a\u0435\u0442\u0430 \u0431\u043e\u043b\u044c\u0448\u0435 \u043d\u0435 \u0431\u0443\u0434\u0435\u0442 \u043f\u043e\u044f\u0432\u043b\u044f\u0442\u044c\u0441\u044f \u0432 \u043f\u043e\u0434\u0431\u043e\u0440\u0435 \u0434\u043b\u044f \u0441\u0435\u043c\u0435\u0439. \u0414\u043b\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u043f\u043e\u0438\u0441\u043a\u0430 \u0441\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u0441\u044f \u0432 \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0435."},
gTm(){return"\u041a\u043e\u0433\u0434\u0430 \u0432\u0430\u043c \u043f\u043e\u043d\u0430\u0434\u043e\u0431\u0438\u0442\u0441\u044f \u043d\u043e\u0432\u0430\u044f \u0440\u0430\u0431\u043e\u0442\u0430, \u0432\u043a\u043b\u044e\u0447\u0438\u0442\u0435 \xab\u0418\u0449\u0443 \u0440\u0430\u0431\u043e\u0442\u0443\xbb \u0432 \u043b\u0438\u0447\u043d\u043e\u043c \u043a\u0430\u0431\u0438\u043d\u0435\u0442\u0435."},
gTw(){return"\u0412\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u0434\u0430\u0442\u0443 \u043f\u0435\u0440\u0432\u043e\u0433\u043e \u0432\u044a\u0435\u0437\u0434\u0430"},
gTx(){return"\u0414\u0430\u0442\u0430 \u043d\u0435 \u043c\u043e\u0436\u0435\u0442 \u0431\u044b\u0442\u044c \u0432 \u0431\u0443\u0434\u0443\u0449\u0435\u043c"},
gTR(){return"\u0417\u0430\u043f\u0440\u043e\u0441 \u0441\u0435\u043c\u044c\u0438"},
gTX(){return"\u0414\u0430\u0442\u0430 \u0441\u0430\u043c\u043e\u0433\u043e \u043f\u0435\u0440\u0432\u043e\u0433\u043e \u0432\u044a\u0435\u0437\u0434\u0430, \u0430 \u043d\u0435 \u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0435\u043d\u0438\u044f \u0438\u0437 \u043e\u0442\u043f\u0443\u0441\u043a\u0430."},
gTY(){return"\u041a\u043e\u0433\u0434\u0430 \u0432\u044b \u0432\u043f\u0435\u0440\u0432\u044b\u0435 \u0432\u044a\u0435\u0445\u0430\u043b\u0438 \u0432 \u0418\u0437\u0440\u0430\u0438\u043b\u044c \u043f\u043e \u0440\u0430\u0431\u043e\u0447\u0435\u0439 \u0432\u0438\u0437\u0435 B/\u20601 \u0432 \u0441\u0444\u0435\u0440\u0435 \u0443\u0445\u043e\u0434\u0430?"},
gCL(){return"\u041f\u0435\u0440\u0432\u044b\u0439 \u0432\u044a\u0435\u0437\u0434 \u0432 \u0418\u0437\u0440\u0430\u0438\u043b\u044c"},
