ga6U(){return"\u0421\u0438\u0434\u0435\u043b\u043a\u0430: \u0438\u043c\u044f, \u0444\u043e\u0442\u043e, \u0433\u0440\u0430\u0436\u0434\u0430\u043d\u0441\u0442\u0432\u043e, \u0433\u043e\u0440\u043e\u0434\u0430 \u0440\u0430\u0431\u043e\u0442\u044b, \u044f\u0437\u044b\u043a\u0438, \u0433\u043e\u0442\u043e\u0432\u043d\u043e\u0441\u0442\u044c \u0438 \u043e\u043f\u044b\u0442, \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u043e\u0441\u0442\u044c, \u0441\u0440\u043e\u043a \u043f\u0440\u0435\u0431\u044b\u0432\u0430\u043d\u0438\u044f \u0432 \u0418\u0437\u0440\u0430\u0438\u043b\u0435 \u0438 \u043f\u0440\u0438\u0447\u0438\u043d\u0430 \u043e\u043a\u043e\u043d\u0447\u0430\u043d\u0438\u044f \u043f\u0440\u043e\u0448\u043b\u043e\u0439 \u0440\u0430\u0431\u043e\u0442\u044b"},
ga70(){return"\u0412\u0438\u0437\u0430: PDF-\u0444\u0430\u0439\u043b \u0438 \u0443\u043a\u0430\u0437\u0430\u043d\u043d\u044b\u0439 \u0441\u0440\u043e\u043a \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f. \u0424\u0430\u0439\u043b \u0437\u0430\u043a\u0440\u044b\u0442, \u0435\u0433\u043e \u0432\u0440\u0443\u0447\u043d\u0443\u044e \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u0442 \u0443\u043f\u043e\u043b\u043d\u043e\u043c\u043e\u0447\u0435\u043d\u043d\u044b\u0439 \u0441\u043e\u0442\u0440\u0443\u0434\u043d\u0438\u043a, \u0438 \u043e\u043d \u043d\u0438\u043a\u043e\u0433\u0434\u0430 \u043d\u0435 \u043f\u0435\u0440\u0435\u0434\u0430\u0451\u0442\u0441\u044f \u0441\u0435\u043c\u044c\u044f\u043c"},
ga6X(){return"\u041f\u043b\u0430\u0442\u0435\u0436\u0438: \u0441\u0443\u043c\u043c\u0430, \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435, \u0432\u0440\u0435\u043c\u044f \u0438 ID \u0442\u0440\u0430\u043d\u0437\u0430\u043a\u0446\u0438\u0438 \u0432 \u043c\u0430\u0433\u0430\u0437\u0438\u043d\u0435. \u0414\u0430\u043d\u043d\u044b\u0435 \u043a\u0430\u0440\u0442\u044b \u043c\u044b \u043d\u0435 \u0445\u0440\u0430\u043d\u0438\u043c"},
ga6W(){return"\u0421\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u044f: \u0442\u043e\u043b\u044c\u043a\u043e \u0442\u0435\u043a\u0441\u0442 \u0438 \u0435\u0433\u043e \u0430\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043f\u0435\u0440\u0435\u0432\u043e\u0434"},
ga6Z(){return"\u041e\u0431\u0440\u0430\u0449\u0435\u043d\u0438\u044f \u0432 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0443, \u0436\u0430\u043b\u043e\u0431\u044b \u0438 \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u044f"},
ga6Y(){return"\u0421\u0432\u043e\u0434\u043d\u044b\u0435 \u0434\u0430\u043d\u043d\u044b\u0435 \u043e\u0431 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u0438, \u0431\u0435\u0437 \u043b\u0438\u0447\u043d\u044b\u0445 \u0434\u0430\u043d\u043d\u044b\u0445 \u0432 \u0441\u043e\u0431\u044b\u0442\u0438\u044f\u0445 \u0430\u043d\u0430\u043b\u0438\u0442\u0438\u043a\u0438"},
ga8I(){return"\u041a\u0442\u043e \u0447\u0442\u043e \u0432\u0438\u0434\u0438\u0442"},
ga8F(){return"\u0414\u043e \u043e\u043f\u043b\u0430\u0442\u044b \u0441\u0435\u043c\u044c\u0438 \u0432\u0438\u0434\u044f\u0442 \u0431\u0430\u0437\u043e\u0432\u0443\u044e \u043a\u0430\u0440\u0442\u043e\u0447\u043a\u0443 \u0431\u0435\u0437 \u043d\u043e\u043c\u0435\u0440\u0430 \u0442\u0435\u043b\u0435\u0444\u043e\u043d\u0430, \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u043e\u0432 \u0438 \u043e\u0446\u0435\u043d\u043a\u0438 \u0441\u043e\u0432\u043f\u0430\u0434\u0435\u043d\u0438\u044f"},
ga8G(){return"\u041d\u043e\u043c\u0435\u0440 \u0442\u0435\u043b\u0435\u0444\u043e\u043d\u0430 \u0432\u044b\u0434\u0430\u0451\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u043c \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435\u043c: \u043a\u043e\u0433\u0434\u0430 \u0443 \u0441\u0435\u043c\u044c\u0438 \u0435\u0441\u0442\u044c \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044e\u0449\u0438\u0439 \u0434\u043e\u0441\u0442\u0443\u043f, \u0430 \u0432\u0438\u0437\u0430 \u0441\u0438\u0434\u0435\u043b\u043a\u0438 \u0443\u0441\u043f\u0435\u0448\u043d\u043e \u043f\u0440\u043e\u0432\u0435\u0440\u0435\u043d\u0430"},
ga8J(){return"\u0424\u0430\u0439\u043b \u0432\u0438\u0437\u044b \u0432\u0438\u0434\u0438\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u0443\u043f\u043e\u043b\u043d\u043e\u043c\u043e\u0447\u0435\u043d\u043d\u044b\u0439 \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u044e\u0449\u0438\u0439, \u0434\u043e \u0443\u0434\u0430\u043b\u0435\u043d\u0438\u044f \u0444\u0430\u0439\u043b\u0430"},
ga8H(){return"\u0423 \u0441\u043e\u0442\u0440\u0443\u0434\u043d\u0438\u043a\u043e\u0432 \u0440\u0430\u0437\u0434\u0435\u043b\u044c\u043d\u044b\u0435 \u043f\u0440\u0430\u0432\u0430 \u043f\u043e \u0440\u043e\u043b\u044f\u043c, \u0438 \u043a\u0430\u0436\u0434\u043e\u0435 \u0438\u0445 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u0437\u0430\u043f\u0438\u0441\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0432 \u0436\u0443\u0440\u043d\u0430\u043b"},
ga7M(){return"\u0421\u043a\u043e\u043b\u044c\u043a\u043e \u0445\u0440\u0430\u043d\u044f\u0442\u0441\u044f \u0434\u0430\u043d\u043d\u044b\u0435"},
ga7L(){return"\u042d\u0442\u043e \u043f\u0440\u0430\u0432\u0438\u043b\u0430, \u0437\u0430\u0434\u0430\u043d\u043d\u044b\u0435 \u0434\u043b\u044f \u043f\u0440\u043e\u0434\u0443\u043a\u0442\u0430. \u041d\u0435\u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u0441\u0440\u043e\u043a\u0438 \u0435\u0449\u0451 \u0436\u0434\u0443\u0442 \u0440\u0435\u0448\u0435\u043d\u0438\u044f"},
ga7H(){return"\u0424\u0430\u0439\u043b \u0432\u0438\u0437\u044b \u0438 \u043f\u0430\u0441\u043f\u043e\u0440\u0442\u043d\u044b\u0435 \u0434\u0430\u043d\u043d\u044b\u0435"},
ga7I(){return"\u0423\u0434\u0430\u043b\u044f\u044e\u0442\u0441\u044f \u0441\u0440\u0430\u0437\u0443 \u043f\u043e\u0441\u043b\u0435 \u0440\u0435\u0448\u0435\u043d\u0438\u044f \u0438 \u043d\u0435 \u043f\u043e\u0437\u0434\u043d\u0435\u0435 \u0447\u0435\u043c \u0447\u0435\u0440\u0435\u0437 24 \u0447\u0430\u0441\u0430 \u043f\u043e\u0441\u043b\u0435 \u0437\u0430\u0433\u0440\u0443\u0437\u043a\u0438"},
ga7J(){return"\u0420\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438 \u0432\u0438\u0437\u044b \u0438 \u0441\u0440\u043e\u043a \u0435\u0451 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f"},
ga7K(){return"\u0414\u043e \u0443\u0434\u0430\u043b\u0435\u043d\u0438\u044f \u0430\u043a\u043a\u0430\u0443\u043d\u0442\u0430"},
ga7z(){return"\u0421\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u044f \u0438 \u043f\u0435\u0440\u0435\u0432\u043e\u0434\u044b"},
ga7A(){return"\u0414\u043e \u043a\u043e\u043d\u0446\u0430 \u043f\u0435\u0440\u0438\u043e\u0434\u0430 \u0434\u043e\u0441\u0442\u0443\u043f\u0430 \u0441\u0435\u043c\u044c\u0438 (28 \u0434\u043d\u0435\u0439), \u0437\u0430\u0442\u0435\u043c \u0443\u0434\u0430\u043b\u044f\u044e\u0442\u0441\u044f \u0443 \u043e\u0431\u0435\u0438\u0445 \u0441\u0442\u043e\u0440\u043e\u043d"},
ga7B(){return"\u041f\u0440\u043e\u0444\u0438\u043b\u044c \u0441\u0435\u043c\u044c\u0438"},
ga7C(){return"28 \u0434\u043d\u0435\u0439 \u0434\u043e\u0441\u0442\u0443\u043f\u0430 \u0438 \u0435\u0449\u0451 30 \u0434\u043d\u0435\u0439 \u0431\u0435\u0437 \u043d\u043e\u0432\u043e\u0439 \u043f\u043e\u043a\u0443\u043f\u043a\u0438, \u0437\u0430\u0442\u0435\u043c \u0443\u0434\u0430\u043b\u044f\u0435\u0442\u0441\u044f"},
ga7x(){return"\u041f\u0440\u043e\u0444\u0438\u043b\u044c \u0441\u0438\u0434\u0435\u043b\u043a\u0438"},
ga7y(){return"\u0423\u0434\u0430\u043b\u044f\u0435\u0442\u0441\u044f \u043f\u043e\u0441\u043b\u0435 30 \u0434\u043d\u0435\u0439 \u043f\u043e\u0434\u0440\u044f\u0434 \u0431\u0435\u0437 \u0432\u0445\u043e\u0434\u0430 \u0438\u043b\u0438 \u043f\u043e \u0437\u0430\u043f\u0440\u043e\u0441\u0443 \u043d\u0430 \u0443\u0434\u0430\u043b\u0435\u043d\u0438\u0435"},
ga7D(){return"\u0417\u0430\u043f\u0438\u0441\u0438 \u043e \u043f\u043b\u0430\u0442\u0435\u0436\u0430\u0445 \u0438 \u0436\u0443\u0440\u043d\u0430\u043b\u044b \u0430\u0443\u0434\u0438\u0442\u0430"},
