ga7F(){return"\u041e\u0431\u0440\u0430\u0449\u0435\u043d\u0438\u044f, \u0436\u0430\u043b\u043e\u0431\u044b, \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0430 \u0438 \u0436\u0443\u0440\u043d\u0430\u043b\u044b"},
ga7G(){return"\u041d\u0435 \u0445\u0440\u0430\u043d\u044f\u0442\u0441\u044f \u0431\u0435\u0441\u0441\u0440\u043e\u0447\u043d\u043e"},
gGj(){return"\u0422\u043e\u0447\u043d\u044b\u0439 \u0441\u0440\u043e\u043a \u0445\u0440\u0430\u043d\u0435\u043d\u0438\u044f \u0436\u0434\u0451\u0442 \u0440\u0435\u0448\u0435\u043d\u0438\u044f \u0438 \u044e\u0440\u0438\u0434\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438"},
ga7u(){return"\u0427\u0442\u043e \u0435\u0449\u0451 \u0432\u0430\u0436\u043d\u043e \u0437\u043d\u0430\u0442\u044c"},
ga7s(){return"\u041f\u043e\u0441\u043b\u0435 \u0443\u0434\u0430\u043b\u0435\u043d\u0438\u044f \u0430\u043a\u043a\u0430\u0443\u043d\u0442\u0430 \u0438\u043c\u044f \u0438 \u0442\u0435\u043b\u0435\u0444\u043e\u043d \u043d\u0435 \u0445\u0440\u0430\u043d\u044f\u0442\u0441\u044f \u0434\u043b\u044f \u0440\u0435\u043a\u043b\u0430\u043c\u044b, \u043c\u0430\u0440\u043a\u0435\u0442\u0438\u043d\u0433\u043e\u0432\u043e\u0439 \u0431\u0430\u0437\u044b \u043d\u0435\u0442"},
ga7t(){return"\u0423\u0432\u0435\u0434\u043e\u043c\u043b\u0435\u043d\u0438\u044f \u043f\u0440\u0438\u0445\u043e\u0434\u044f\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u043e \u043d\u043e\u0432\u043e\u043c \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0438 \u0438 \u043e \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u0438\u0438 \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u043e\u0441\u0442\u0438, \u0431\u0435\u0437 \u0438\u043c\u0435\u043d\u0438, \u0442\u0435\u043a\u0441\u0442\u0430 \u0438 \u043b\u0438\u0447\u043d\u044b\u0445 \u0434\u0430\u043d\u043d\u044b\u0445 \u043d\u0430 \u044d\u043a\u0440\u0430\u043d\u0435 \u0431\u043b\u043e\u043a\u0438\u0440\u043e\u0432\u043a\u0438"},
ga7r(){return"\u041e\u043f\u043b\u0430\u0442\u0430 \u043f\u0440\u043e\u0445\u043e\u0434\u0438\u0442 \u0447\u0435\u0440\u0435\u0437 \u043c\u0430\u0433\u0430\u0437\u0438\u043d \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0439. \u041f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u043d\u0435 \u0445\u0440\u0430\u043d\u0438\u0442 \u0434\u0430\u043d\u043d\u044b\u0435 \u043a\u0430\u0440\u0442\u044b"},
